<?php
declare(strict_types=1);
namespace App\Repositories;
use PDO; use RuntimeException;
final class TicProvisioningRepository
{
 public function __construct(private PDO $db){}
 public function requests(string $filter='ACTIVAS'):array{
  $allowed=['ACTIVAS','PENDIENTE','EN_REVISION','EJECUTADA','RECHAZADA','ERROR','TODAS']; if(!in_array($filter,$allowed,true))$filter='ACTIVAS';
  $where=$filter==='TODAS'?'1=1':($filter==='ACTIVAS'?"esc.codigo IN ('PENDIENTE','EN_REVISION','APROBADA','ERROR','EJECUTANDO')":"esc.codigo=".$this->db->quote($filter));
  return $this->db->query("SELECT sc.id,sc.numero_solicitud,sc.fecha_solicitud,sc.fecha_ejecucion,esc.codigo estado_codigo,esc.nombre estado,tsc.codigo tipo_codigo,tsc.nombre tipo,pf.codigo perfil_codigo,pf.nombre perfil,p.numero_identificacion,CONCAT_WS(' ',p.primer_nombre,p.segundo_nombre,p.primer_apellido,p.segundo_apellido) nombre FROM solicitudes_cuentas sc JOIN estados_solicitud_cuenta esc ON esc.id=sc.estado_solicitud_id JOIN tipos_solicitud_cuenta tsc ON tsc.id=sc.tipo_solicitud_id JOIN personas p ON p.id=sc.persona_id LEFT JOIN perfiles pf ON pf.id=sc.perfil_solicitado_id WHERE $where ORDER BY sc.fecha_solicitud DESC,sc.id DESC LIMIT 500")->fetchAll();
 }
 public function request(int $id):?array{$s=$this->db->prepare("SELECT sc.*,esc.codigo estado_codigo,esc.nombre estado,tsc.codigo tipo_codigo,tsc.nombre tipo,osc.codigo origen_codigo,pf.codigo perfil_codigo,pf.nombre perfil,p.numero_identificacion,p.primer_nombre,p.segundo_nombre,p.primer_apellido,p.segundo_apellido,CONCAT_WS(' ',p.primer_nombre,p.segundo_nombre,p.primer_apellido,p.segundo_apellido) nombre FROM solicitudes_cuentas sc JOIN estados_solicitud_cuenta esc ON esc.id=sc.estado_solicitud_id JOIN tipos_solicitud_cuenta tsc ON tsc.id=sc.tipo_solicitud_id JOIN origenes_solicitud_cuenta osc ON osc.id=sc.origen_solicitud_id JOIN personas p ON p.id=sc.persona_id LEFT JOIN perfiles pf ON pf.id=sc.perfil_solicitado_id WHERE sc.id=:id LIMIT 1");$s->execute(['id'=>$id]);return $s->fetch()?:null;}
 public function usernames(int $id):array{$s=$this->db->prepare("SELECT scu.*,ecu.codigo estado_codigo,ecu.nombre estado FROM solicitud_cuenta_usernames scu JOIN estados_candidato_username ecu ON ecu.id=scu.estado_candidato_id WHERE scu.solicitud_cuenta_id=:id ORDER BY orden_intento");$s->execute(['id'=>$id]);return $s->fetchAll();}
 public function generateCandidates(int $id,string $domain):void{$r=$this->request($id);if(!$r)throw new RuntimeException('Solicitud no encontrada.');$parts=[];foreach([[$r['primer_nombre'],$r['primer_apellido']],[$r['segundo_nombre'],$r['primer_apellido']],[$r['primer_nombre'],$r['segundo_apellido']],[$r['segundo_nombre'],$r['segundo_apellido']]] as [$n,$a]){if(trim((string)$n)===''||trim((string)$a)==='')continue;$u=$this->slug($n).'.'.$this->slug($a);if($u!=='.')$parts[]=$u;}$parts=array_values(array_unique($parts));$state=(int)$this->scalar("SELECT id FROM estados_candidato_username WHERE codigo='PENDIENTE'");$this->db->prepare('DELETE FROM solicitud_cuenta_usernames WHERE solicitud_cuenta_id=:s AND seleccionado=0')->execute(['s'=>$id]);$ins=$this->db->prepare('INSERT IGNORE INTO solicitud_cuenta_usernames(solicitud_cuenta_id,estado_candidato_id,orden_intento,username,email_propuesto) VALUES(:s,:e,:o,:u,:m)');foreach($parts as $i=>$u)$ins->execute(['s'=>$id,'e'=>$state,'o'=>$i+1,'u'=>$u,'m'=>$u.'@'.$domain]);}
 public function markCandidate(int $candidate,string $status,string $detail):void{$st=(int)$this->scalar("SELECT id FROM estados_candidato_username WHERE codigo=".$this->db->quote($status));$s=$this->db->prepare('UPDATE solicitud_cuenta_usernames SET estado_candidato_id=:e,fecha_validacion=NOW(),detalle_validacion=:d WHERE id=:id');$s->execute(['e'=>$st,'d'=>$detail,'id'=>$candidate]);}
 public function selectCandidate(int $requestId,int $candidate):array{$this->db->beginTransaction();try{$sel=(int)$this->scalar("SELECT id FROM estados_candidato_username WHERE codigo='SELECCIONADO'");$this->db->prepare('UPDATE solicitud_cuenta_usernames SET seleccionado=0 WHERE solicitud_cuenta_id=:s')->execute(['s'=>$requestId]);$q=$this->db->prepare('UPDATE solicitud_cuenta_usernames SET seleccionado=1,estado_candidato_id=:e WHERE id=:id AND solicitud_cuenta_id=:s');$q->execute(['e'=>$sel,'id'=>$candidate,'s'=>$requestId]);if(!$q->rowCount())throw new RuntimeException('Candidato inválido.');$this->db->commit();$s=$this->db->prepare('SELECT * FROM solicitud_cuenta_usernames WHERE id=:id');$s->execute(['id'=>$candidate]);return $s->fetch();}catch(\Throwable $e){$this->db->rollBack();throw $e;}}
 public function selected(int $requestId):?array{$s=$this->db->prepare('SELECT * FROM solicitud_cuenta_usernames WHERE solicitud_cuenta_id=:s AND seleccionado=1 LIMIT 1');$s->execute(['s'=>$requestId]);return $s->fetch()?:null;}
 public function setReview(int $id,int $actor):void{$state=(int)$this->scalar("SELECT id FROM estados_solicitud_cuenta WHERE codigo='EN_REVISION'");$s=$this->db->prepare("UPDATE solicitudes_cuentas SET estado_solicitud_id=:e,revisado_por_usuario_id=:a,fecha_revision=COALESCE(fecha_revision,NOW()) WHERE id=:id AND estado_solicitud_id IN (SELECT id FROM estados_solicitud_cuenta WHERE codigo IN ('PENDIENTE','EN_REVISION'))");$s->execute(['e'=>$state,'a'=>$actor,'id'=>$id]);}
 public function licenseTypes():array{return $this->db->query("SELECT l.id,l.codigo,l.nombre,l.sku_externo FROM tipos_licencia_institucional l JOIN proveedores_identidad p ON p.id=l.proveedor_identidad_id WHERE p.codigo='MICROSOFT_ENTRA' AND l.activo=1 ORDER BY l.nombre")->fetchAll();}
 public function saveSku(int $licenseId,string $sku):void{$s=$this->db->prepare('UPDATE tipos_licencia_institucional SET sku_externo=:sku WHERE id=:id');$s->execute(['sku'=>$sku,'id'=>$licenseId]);}
 public function defaultLicenseForProfile(?int $profileId):?array{if(!$profileId)return null;$s=$this->db->prepare("SELECT l.* FROM licencia_microsoft_perfiles mp JOIN tipos_licencia_institucional l ON l.id=mp.tipo_licencia_id WHERE mp.perfil_id=:p AND mp.activo=1 AND l.activo=1 ORDER BY mp.es_predeterminada DESC,mp.prioridad,l.id LIMIT 1");$s->execute(['p'=>$profileId]);return $s->fetch()?:null;}
 public function accounts():array{return $this->db->query("SELECT ci.id,ci.identificador_externo,ci.username,ci.email_institucional,ci.ultima_sincronizacion_at,eci.codigo estado_codigo,eci.nombre estado,u.id usuario_id,p.numero_identificacion,CONCAT_WS(' ',p.primer_nombre,p.segundo_nombre,p.primer_apellido,p.segundo_apellido) nombre,GROUP_CONCAT(DISTINCT pf.nombre ORDER BY pf.nombre SEPARATOR ', ') perfiles,GROUP_CONCAT(DISTINCT tl.nombre ORDER BY tl.nombre SEPARATOR ', ') licencias FROM cuentas_institucionales ci JOIN estados_cuenta_institucional eci ON eci.id=ci.estado_cuenta_id JOIN usuarios u ON u.id=ci.usuario_id JOIN personas p ON p.id=u.persona_id LEFT JOIN usuario_perfiles up ON up.usuario_id=u.id AND up.activo=1 LEFT JOIN perfiles pf ON pf.id=up.perfil_id LEFT JOIN cuenta_licencias cl ON cl.cuenta_institucional_id=ci.id AND cl.activa=1 LEFT JOIN tipos_licencia_institucional tl ON tl.id=cl.tipo_licencia_id WHERE ci.deleted_at IS NULL GROUP BY ci.id,ci.identificador_externo,ci.username,ci.email_institucional,ci.ultima_sincronizacion_at,eci.codigo,eci.nombre,u.id,p.numero_identificacion,p.primer_nombre,p.segundo_nombre,p.primer_apellido,p.segundo_apellido ORDER BY nombre")->fetchAll();}
 public function account(int $id):?array{$s=$this->db->prepare("SELECT ci.*,eci.codigo estado_codigo,eci.nombre estado,u.id usuario_id,p.numero_identificacion,CONCAT_WS(' ',p.primer_nombre,p.segundo_nombre,p.primer_apellido,p.segundo_apellido) nombre,GROUP_CONCAT(DISTINCT pf.nombre ORDER BY pf.nombre SEPARATOR ', ') perfiles,GROUP_CONCAT(DISTINCT CONCAT(tl.nombre,' [',COALESCE(tl.sku_externo,'sin SKU'),']') ORDER BY tl.nombre SEPARATOR ', ') licencias FROM cuentas_institucionales ci JOIN estados_cuenta_institucional eci ON eci.id=ci.estado_cuenta_id JOIN usuarios u ON u.id=ci.usuario_id JOIN personas p ON p.id=u.persona_id LEFT JOIN usuario_perfiles up ON up.usuario_id=u.id AND up.activo=1 LEFT JOIN perfiles pf ON pf.id=up.perfil_id LEFT JOIN cuenta_licencias cl ON cl.cuenta_institucional_id=ci.id AND cl.activa=1 LEFT JOIN tipos_licencia_institucional tl ON tl.id=cl.tipo_licencia_id WHERE ci.id=:id AND ci.deleted_at IS NULL GROUP BY ci.id,eci.codigo,eci.nombre,u.id,p.numero_identificacion,p.primer_nombre,p.segundo_nombre,p.primer_apellido,p.segundo_apellido LIMIT 1");$s->execute(['id'=>$id]);return $s->fetch()?:null;}
 public function accountEvents(int $id):array{$s=$this->db->prepare("SELECT ce.*,tec.codigo tipo_codigo,tec.nombre tipo,CONCAT_WS(' ',p.primer_nombre,p.primer_apellido) actor FROM cuenta_eventos ce JOIN tipos_evento_cuenta tec ON tec.id=ce.tipo_evento_id LEFT JOIN usuarios u ON u.id=ce.ejecutado_por_usuario_id LEFT JOIN personas p ON p.id=u.persona_id WHERE ce.cuenta_institucional_id=:id ORDER BY ce.created_at DESC,ce.id DESC LIMIT 100");$s->execute(['id'=>$id]);return $s->fetchAll();}
 public function logAccountEvent(int $accountId,string $type,int $actor,string $detail,array $data=[]):void{$tid=(int)$this->scalar("SELECT id FROM tipos_evento_cuenta WHERE codigo=".$this->db->quote($type)." LIMIT 1");if(!$tid)return;$s=$this->db->prepare('INSERT INTO cuenta_eventos(cuenta_institucional_id,tipo_evento_id,ejecutado_por_usuario_id,origen,detalle,datos_json) VALUES(:c,:t,:u,\'TIC\',:d,:j)');$s->execute(['c'=>$accountId,'t'=>$tid,'u'=>$actor,'d'=>$detail,'j'=>$data?json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES):null]);}
 public function provisionLocal(int $requestId,array $ms,string $username,string $email,int $actor,?int $licenseId):array{$this->db->beginTransaction();try{$r=$this->request($requestId);if(!$r)throw new RuntimeException('Solicitud no encontrada.');$uid=(int)$this->scalar('SELECT id FROM usuarios WHERE persona_id='.(int)$r['persona_id'].' AND deleted_at IS NULL LIMIT 1');$active=(int)$this->scalar("SELECT id FROM estados_usuario WHERE codigo='ACTIVO' LIMIT 1");if(!$uid){$s=$this->db->prepare('INSERT INTO usuarios(persona_id,estado_usuario_id,requiere_actualizacion_datos,activo) VALUES(:p,:e,1,1)');$s->execute(['p'=>$r['persona_id'],'e'=>$active]);$uid=(int)$this->db->lastInsertId();}else{$this->db->prepare('UPDATE usuarios SET estado_usuario_id=:e,activo=1 WHERE id=:u')->execute(['e'=>$active,'u'=>$uid]);}if($r['perfil_solicitado_id']){$s=$this->db->prepare("INSERT INTO usuario_perfiles(usuario_id,perfil_id,activo,asignado_por_usuario_id) VALUES(:u,:p,1,:a) ON DUPLICATE KEY UPDATE activo=1,fecha_fin=NULL,asignado_por_usuario_id=VALUES(asignado_por_usuario_id)");$s->execute(['u'=>$uid,'p'=>$r['perfil_solicitado_id'],'a'=>$actor]);}$provider=(int)$this->scalar("SELECT id FROM proveedores_identidad WHERE codigo='MICROSOFT_ENTRA'");$accountState=(int)$this->scalar("SELECT id FROM estados_cuenta_institucional WHERE codigo='ACTIVA'");$domain=substr(strrchr($email,'@'),1);$s=$this->db->prepare('SELECT id FROM cuentas_institucionales WHERE usuario_id=:u AND proveedor_identidad_id=:p AND deleted_at IS NULL LIMIT 1');$s->execute(['u'=>$uid,'p'=>$provider]);$cid=(int)($s->fetchColumn()?:0);if(!$cid){$s=$this->db->prepare('INSERT INTO cuentas_institucionales(usuario_id,proveedor_identidad_id,estado_cuenta_id,identificador_externo,username,email_institucional,tenant_id,dominio,ubicacion_uso,fecha_creacion_externa,fecha_activacion,ultima_sincronizacion_at,activo) VALUES(:u,:p,:e,:oid,:un,:mail,:tid,:d,\'EC\',NOW(),NOW(),NOW(),1)');$s->execute(['u'=>$uid,'p'=>$provider,'e'=>$accountState,'oid'=>$ms['id'],'un'=>$username,'mail'=>$email,'tid'=>$_ENV['MICROSOFT_TENANT_ID']??null,'d'=>$domain]);$cid=(int)$this->db->lastInsertId();}else{$s=$this->db->prepare('UPDATE cuentas_institucionales SET estado_cuenta_id=:e,identificador_externo=:oid,username=:un,email_institucional=:mail,ultima_sincronizacion_at=NOW(),activo=1 WHERE id=:id');$s->execute(['e'=>$accountState,'oid'=>$ms['id'],'un'=>$username,'mail'=>$email,'id'=>$cid]);}if($licenseId){$s=$this->db->prepare('SELECT id FROM cuenta_licencias WHERE cuenta_institucional_id=:c AND tipo_licencia_id=:l AND activa=1 LIMIT 1');$s->execute(['c'=>$cid,'l'=>$licenseId]);if(!$s->fetchColumn()){$s=$this->db->prepare('INSERT INTO cuenta_licencias(cuenta_institucional_id,tipo_licencia_id,asignada_por_usuario_id,activa) VALUES(:c,:l,:a,1)');$s->execute(['c'=>$cid,'l'=>$licenseId,'a'=>$actor]);}}$done=(int)$this->scalar("SELECT id FROM estados_solicitud_cuenta WHERE codigo='EJECUTADA'");$this->db->prepare('UPDATE solicitudes_cuentas SET estado_solicitud_id=:e,revisado_por_usuario_id=COALESCE(revisado_por_usuario_id,:reviewer),aprobado_por_usuario_id=:approver,fecha_revision=COALESCE(fecha_revision,NOW()),fecha_aprobacion=NOW(),fecha_ejecucion=NOW() WHERE id=:id')->execute(['e'=>$done,'reviewer'=>$actor,'approver'=>$actor,'id'=>$requestId]);$ps=(int)$this->scalar("SELECT id FROM estados_provisionamiento_cuenta WHERE codigo='COMPLETADO'");$this->db->prepare('INSERT INTO provisionamientos_cuenta(solicitud_cuenta_id,estado_provisionamiento_id,cuenta_institucional_id,usuario_siga_id,intento_actual,fecha_inicio,fecha_fin) VALUES(:s,:e,:c,:u,1,NOW(),NOW()) ON DUPLICATE KEY UPDATE estado_provisionamiento_id=VALUES(estado_provisionamiento_id),cuenta_institucional_id=VALUES(cuenta_institucional_id),usuario_siga_id=VALUES(usuario_siga_id),intento_actual=intento_actual+1,fecha_fin=NOW(),ultimo_error_codigo=NULL,ultimo_error_mensaje=NULL')->execute(['s'=>$requestId,'e'=>$ps,'c'=>$cid,'u'=>$uid]);$this->db->commit();return ['user_id'=>$uid,'account_id'=>$cid];}catch(\Throwable $e){$this->db->rollBack();throw $e;}}
 private function slug(string $v):string{$v=iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$v)?:$v;$v=strtolower(trim($v));return preg_replace('/[^a-z0-9]+/','',$v)??'';}
 private function scalar(string $sql):mixed{return $this->db->query($sql)->fetchColumn();}
}
